1	"use client";
2	
3	import { useEffect, useState } from "react";
4	import Link from "next/link";
5	import { isChunkLoadError, reloadForChunkErrorOnce } from "@/lib/chunk-error";
6	
7	export function ErrorState({
8	  error,
9	  reset,
10	  context,
11	  home = "/",
12	  homeLabel = "Go home",
13	}: {
14	  error: Error & { digest?: string };
15	  reset: () => void;
16	  context: string;
17	  home?: string;
18	  homeLabel?: string;
19	}) {
20	  const [reloading, setReloading] = useState(false);
21	
22	  useEffect(() => {
23	    // Best-effort report to the server error pipeline.
24	    try {
25	      fetch("/api/log", {
26	        method: "POST",
27	        headers: { "content-type": "application/json" },
28	        body: JSON.stringify({
29	          context,
30	          message: error?.message,
31	          digest: error?.digest,
32	          stack: error?.stack,
33	          path: typeof window !== "undefined" ? window.location.pathname : undefined,
34	        }),
35	        keepalive: true,
36	      }).catch(() => {});
37	    } catch {
38	      /* ignore */
39	    }
40	  }, [error, context]);
41	
42	  useEffect(() => {
43	    if (!isChunkLoadError(error)) return;
44	    if (reloadForChunkErrorOnce()) setReloading(true);
45	  }, [error]);
46	
47	  if (reloading) {
48	    return (
49	      <div className="grid min-h-[70vh] place-items-center px-4 py-16">
50	        <p className="text-sm text-slate-400">Updating…</p>
51	      </div>
52	    );
53	  }
54	
55	  return (
56	    <div className="grid min-h-[70vh] place-items-center px-4 py-16">
57	      <div className="card max-w-md text-center">
58	        <div className="mx-auto mb-4 grid h-12 w-12 place-items-center rounded-full bg-red-500/10 text-2xl">⚠️</div>
59	        <h1 className="mb-2 text-xl font-semibold">Something went wrong</h1>
60	        <p className="mb-1 text-sm text-slate-400">
61	          We hit an unexpected error and our team has been notified. You can retry, or head back.
62	        </p>
63	        {error?.digest && (
64	          <p className="mb-5 font-mono text-xs text-slate-600">ref: {error.digest}</p>
65	        )}
66	        <div className="flex items-center justify-center gap-3">
67	          <button onClick={() => reset()} className="btn-primary">
68	            Try again
69	          </button>
70	          <Link href={home} className="btn-secondary">
71	            {homeLabel}
72	          </Link>
73	        </div>
74	      </div>
75	    </div>
76	  );
77	}
