71	const statusColors: Record<string, { dot: string; text: string; pulse?: boolean }> = {
72	  RUNNING: { dot: "bg-emerald-400", text: "text-emerald-400", pulse: true },
73	  online: { dot: "bg-emerald-400", text: "text-emerald-400", pulse: true },
74	  STOPPED: { dot: "bg-slate-500", text: "text-slate-400" },
75	  PENDING: { dot: "bg-amber-400", text: "text-amber-400" },
76	  PROVISIONING: { dot: "bg-amber-400", text: "text-amber-400", pulse: true },
77	  REINSTALLING: { dot: "bg-amber-400", text: "text-amber-400", pulse: true },
78	  DELETING: { dot: "bg-red-400", text: "text-red-400", pulse: true },
79	  SUSPENDED: { dot: "bg-red-400", text: "text-red-400" },
80	  ERROR: { dot: "bg-red-400", text: "text-red-400" },
81	  QUEUED: { dot: "bg-amber-400", text: "text-amber-400" },
82	  DONE: { dot: "bg-emerald-400", text: "text-emerald-400" },
83	  // A migration that ran every step but left a source domain dark or a migrated
84	  // service crash-looping. Amber on purpose: with no entry here it falls back to
85	  // STOPPED's neutral grey and reads as "nothing to see" — the exact false
86	  // reassurance this status exists to prevent.
87	  COMPLETED_WITH_ISSUES: { dot: "bg-amber-400", text: "text-amber-400" },
88	  FAILED: { dot: "bg-red-400", text: "text-red-400" },
89	  OPEN: { dot: "bg-amber-400", text: "text-amber-400" },
90	  ANSWERED: { dot: "bg-brand-300", text: "text-brand-300" },
91	  CUSTOMER_REPLY: { dot: "bg-amber-400", text: "text-amber-400" },
92	  CLOSED: { dot: "bg-slate-500", text: "text-slate-400" },
93	  // Block storage volumes (Volume.status) + business email (EmailSubscription.status).
94	  // PENDING / SUSPENDED / DELETING are already covered above and behave the same here.
95	  ACTIVE: { dot: "bg-emerald-400", text: "text-emerald-400", pulse: true },
96	  ATTACHED: { dot: "bg-emerald-400", text: "text-emerald-400" },
97	  DETACHED: { dot: "bg-slate-500", text: "text-slate-400" },
98	  CANCELLED: { dot: "bg-slate-500", text: "text-slate-400" },
99	};
