156	body {
157	  @apply bg-navy-950 text-slate-100 antialiased font-sans;
158	  background-image:
159	    radial-gradient(ellipse 80% 50% at 20% -10%, rgb(111 71 245 / 0.13), transparent),
160	    radial-gradient(ellipse 60% 40% at 90% 0%, rgb(59 130 246 / 0.10), transparent);
161	  background-attachment: fixed;
162	}
