169	@layer components {
170	  /* Surfaces */
171	  .card {
172	    @apply rounded-2xl border border-white/[0.06] bg-navy-900/70 p-6 backdrop-blur-md;
173	    box-shadow: 0 1px 0 0 rgb(255 255 255 / 0.03) inset, 0 8px 32px -12px rgb(0 0 0 / 0.5);
174	  }
175	  .card-hover {
176	    @apply transition-all duration-200 hover:border-brand-500/30 hover:bg-navy-850/80;
177	  }
178	  .glass {
179	    @apply rounded-2xl border border-white/[0.08] bg-white/[0.03] backdrop-blur-xl;
180	  }
181	  .glow-brand {
182	    box-shadow: 0 0 40px -8px rgb(111 71 245 / 0.35);
183	  }
184	  /* The auth-card glow ring — ported directly from Kodely's PromptHero
185	     "chasing light" ring (components/marketing/PromptHero.tsx +
186	     app/globals.css there), recoloured to Nxeon's blue -> violet -> cyan
187	     family instead of Kodely's pink/purple/orange. Same technique, kept
188	     intact rather than reinvented:
189	     - Each layer is a STATIC outer clipper (.glow-clip-a/-b, position, plain
190	       overflow:hidden, never transforms) containing one OVERSIZED inner
191	       rotator (.glow-spin-a/-b, a 200%-wide square via SPIN_SQUARE in
192	       AuthShell.tsx, centered) carrying the conic-gradient background. Only
193	       the inner rotator spins via plain `transform: rotate()`; being
194	       oversized, its corners sweeping outside a same-sized box never matter
195	       because the static outer clipper crops them at every angle.
196	     - The blur lives on the CLIP element, not the rotating child, because
197	       filters apply after the element's own overflow:hidden clipping — that
198	       ordering is what lets the light bleed softly past the clip's edge
199	       instead of surviving as a hard-edged ring.
200	     - The card sitting on top (relative z-10, opaque) covers the rotator's
201	       entire interior, leaving only the outer few px visible as a ring.
202	     - Entrance fade-in, then a slow ambient pulse picking up from the same
203	       opacity the fade-in settled on (no jump at the handoff). */
204	  @keyframes glow-spin {
205	    to {
206	      transform: rotate(360deg);
207	    }
208	  }
209	  .glow-spin-a {
210	    animation: glow-spin 9s linear infinite;
211	  }
212	  .glow-spin-b {
213	    animation: glow-spin 14s linear infinite reverse;
214	  }
215	  @keyframes glow-fade-in-a {
216	    from {
217	      opacity: 0;
218	      transform: scale(0.94);
219	    }
220	    to {
221	      opacity: 0.22;
222	      transform: scale(1);
223	    }
224	  }
225	  @keyframes glow-fade-in-b {
226	    from {
227	      opacity: 0;
228	      transform: scale(0.94);
229	    }
230	    to {
231	      opacity: 0.13;
232	      transform: scale(1);
233	    }
234	  }
235	  @keyframes glow-pulse-a {
